(function(){var loadHandler=window['sl_{73A53C97-72DA-45CF-9CFF-054D6C4F2812}'];loadHandler&&loadHandler(21, '<div id="spr0_1049f4f8"><div id="spr1_1049f4f8" class="kern slide"><img id="img3_1049f4f8" src="data:image/png;base64," width="1280px" height="720px" alt="" style="left:0px;top:0px;"/><div id="spr3_1049f4f8" style="left:986.15px;top:648.5px;"><div id="spr4_1049f4f8"><img id="img0_1049f4f8" src="data:image/png;base64," width="273.75" height="62.25" alt="" style="left:0.06px;top:-0.094px;"/></div></div></div><div id="spr2_1049f4f8" class="kern slide"><div id="spr5_1049f4f8" style="left:71.415px;top:24.353px;"><div id="spr6_1049f4f8"><img id="img1_1049f4f8" src="data:image/png;base64," width="675" height="44.25" alt="" style="left:-0.063px;top:-0.034px;"/></div></div><div id="spr7_1049f4f8" style="left:57.469px;top:78.065px;"><div style="width:0px;"><span id="txt0_1049f4f8" class="nokern" data-width="870.132141" style="left:9.598px;top:1.931px;">A nerve impulse is an electrochemical process that results from the movement of ions across a</span></div><div style="width:0px;"><span id="txt1_1049f4f8" class="nokern" data-width="720.164673" style="left:9.598px;top:29.131px;">neuron\'s semi-permeable membrane (through voltage sensitive ion channels).</span></div><div style="width:0px;"><span id="txt2_1049f4f8" class="nokern" data-width="310.117188" style="left:9.598px;top:88.864px;">Also known as an action potential</span></div></div><div id="svg0_1049f4f8" style="left:1095.547px;top:637.019px;"><svg width="154" height="38" viewBox="0 0 154 38"><path fill="#fee599" d="M0,0 h153.6 v37.44 h-153.6 Z"/></svg></div><div id="spr8_1049f4f8" style="left:1095.547px;top:637.019px;"><div style="width:0px;"><span id="txt3_1049f4f8" class="nokern relpos" data-width="66.201172" style="left:9.598px;top:4.764px;">Book A  </span> <span id="txt4_1049f4f8" class="nokern relpos" data-width="62.023438" style="left:9.592px;top:1.931px;">Page 4</span></div></div><div id="svg1_1049f4f8" style="left:668.536px;top:209.77px;"><svg width="529" height="113" viewBox="0 0 529 113"><path fill="#e2f0d9" d="M0,0 h528.772 v112.374 h-528.772 Z"/></svg></div><div id="spr9_1049f4f8" style="left:668.536px;top:209.77px;"><div style="width:0px;"><span id="txt5_1049f4f8" class="nokern" data-width="399.984375" style="left:9.6px;top:8.185px;">A nerve impulse (action potential) is an</span></div><div style="width:0px;"><span id="txt6_1049f4f8" class="nokern" data-width="499.394531" style="left:9.6px;top:42.745px;">electrochemical signal caused by ion movement</span></div><div style="width:0px;"><span id="txt7_1049f4f8" class="nokern" data-width="312.539062" style="left:9.6px;top:77.305px;">across the neuron membrane.</span></div></div><div id="svg2_1049f4f8" style="left:668.536px;top:208.654px;"><svg width="529" height="78" viewBox="0 0 529 78"><path fill="#e2f0d9" d="M0,0 h528.772 v77.476 h-528.772 Z"/></svg></div><div id="spr10_1049f4f8" style="left:668.536px;top:208.654px;"><div style="width:0px;"><span id="txt8_1049f4f8" class="nokern relpos" data-width="26.777344" style="left:9.6px;top:8.185px;">At </span> <span id="txt9_1049f4f8" class="nokern relpos" data-width="184.382812" style="left:9.593px;top:8.185px;">resting potential </span> <span id="txt10_1049f4f8" class="nokern relpos" data-width="281.812500" style="left:9.587px;top:8.185px;">(around –70 mV), the inside</span></div><div style="width:0px;"><span id="txt11_1049f4f8" class="nokern" data-width="365.167969" style="left:9.6px;top:42.745px;">of the neuron is negatively charged.</span></div></div><div id="svg3_1049f4f8" style="left:668.536px;top:209.212px;"><svg width="529" height="183" viewBox="0 0 529 183"><path fill="#e2f0d9" d="M0,0 h528.772 v182.169 h-528.772 Z"/></svg></div><div id="spr11_1049f4f8" style="left:668.536px;top:209.212px;"><div style="width:0px;"><span id="txt12_1049f4f8" class="nokern relpos" data-width="319.242188" style="left:9.6px;top:8.185px;">When stimulated to threshold, </span> <span id="txt13_1049f4f8" class="nokern relpos" data-width="124.417969" style="left:9.593px;top:8.185px;">sodium (Na</span> <span id="txt14_1049f4f8" class="nokern relpos" style="left:9.587px;top:4.822px;">⁺</span> <span id="txt15_1049f4f8" class="nokern relpos" style="left:9.58px;top:8.185px;">)</span></div><div style="width:0px;"><span id="txt16_1049f4f8" class="nokern relpos" data-width="123.714844" style="left:9.6px;top:42.745px;">ions flow in</span> <span id="txt17_1049f4f8" class="nokern relpos" data-width="372.000000" style="left:9.593px;top:42.745px;">, causing depolarization (membrane</span></div><div style="width:0px;"><span id="txt18_1049f4f8" class="nokern" data-width="196.570312" style="left:9.6px;top:77.305px;">becomes positive).</span></div><div style="width:0px;"><span id="txt19_1049f4f8" class="nokern relpos" data-width="55.464844" style="left:9.6px;top:111.865px;">Then </span> <span id="txt20_1049f4f8" class="nokern relpos" data-width="142.945312" style="left:9.593px;top:111.865px;">potassium (K</span> <span id="txt21_1049f4f8" class="nokern relpos" style="left:9.587px;top:108.502px;">⁺</span> <span id="txt22_1049f4f8" class="nokern relpos" data-width="151.535156" style="left:9.58px;top:111.865px;">) ions flow out</span> <span id="txt23_1049f4f8" class="nokern relpos" data-width="113.285156" style="left:9.573px;top:111.865px;">, leading to</span></div><div style="width:0px;"><span id="txt24_1049f4f8" class="nokern" data-width="432.832031" style="left:9.6px;top:146.425px;">repolarization (return to negative charge)..</span></div></div><div id="svg4_1049f4f8" style="left:668.536px;top:209.77px;"><svg width="529" height="183" viewBox="0 0 529 183"><path fill="#e2f0d9" d="M0,0 h528.772 v182.169 h-528.772 Z"/></svg></div><div id="spr12_1049f4f8" style="left:668.536px;top:209.77px;"><div style="width:0px;"><span id="txt25_1049f4f8" class="nokern relpos" data-width="148.054688" style="left:9.6px;top:8.185px;">An overshoot (</span> <span id="txt26_1049f4f8" class="nokern relpos" data-width="192.539062" style="left:9.593px;top:8.185px;">hyperpolarization</span> <span id="txt27_1049f4f8" class="nokern relpos" data-width="150.187500" style="left:9.587px;top:8.185px;">) briefly makes</span></div><div style="width:0px;"><span id="txt28_1049f4f8" class="nokern" data-width="488.753906" style="left:9.6px;top:42.745px;">the neuron more negative than resting potential</span></div><div style="width:0px;"><span id="txt29_1049f4f8" class="nokern" data-width="277.265625" style="left:9.6px;top:77.305px;">before balance is restored.</span></div><div style="width:0px;"><span id="txt30_1049f4f8" class="nokern" data-width="486.820312" style="left:9.6px;top:111.865px;">The impulse travels along the axon as this wave</span></div><div style="width:0px;"><span id="txt31_1049f4f8" class="nokern" data-width="457.347656" style="left:9.6px;top:146.425px;">of depolarization and repolarization repeats.</span></div></div><div id="spr13_1049f4f8" style="left:73.294px;top:230.161px;"><div id="spr14_1049f4f8"><div id="spr15_1049f4f8"><img id="img2_1049f4f8" src="data:image/png;base64," width="554.25" height="429.75" alt="" style="left:-0.059px;top:-0.064px;"/></div></div><div id="svg5_1049f4f8" style="left:327.282px;top:321.265px;"><svg width="17" height="10" viewBox="-0.763 -0.56 17 10"><g fill="#767171" stroke="none"><path stroke="#767171" stroke-width="1" stroke-linecap="butt" transform="translate(-401.339111,-551.985779)" d="M401.576,560.24 L416.088,552.426"/></g></svg></div></div></div></div>', '{"s":[]}');})();